mapper.select:
/* AppTbm01Mapper.selectMyAttendance */
SELECT
      ATTENDANCE_CD          AS attendanceCd
    , SESSION_CD             AS sessionCd
    , ENTRY_AT               AS entryAt
    , ENTRY_DISTANCE_M       AS entryDistanceM
    , EXIT_AT                AS exitAt
    , EXIT_TYPE_CD           AS exitTypeCd
    , COMPLETION_STATUS_CD   AS completionStatusCd
FROM TB_TBM_ATTENDANCE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'

/* AppTbm01Mapper.selectAttendanceSlot */
SELECT
      ATTENDANCE_CD AS attendanceCd
    , DEL_YN         AS delYn
FROM TB_TBM_ATTENDANCE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
LIMIT 1

mapper.insert:
/* AppTbm01Mapper.insertAttendance */
INSERT INTO TB_TBM_ATTENDANCE (
      ATTENDANCE_CD
    , CMPNY_CD
    , SESSION_CD
    , USER_TYPE_CD
    , USER_CD
    , ENTRY_TYPE_CD
    , ENTRY_AT
    , ENTRY_GPS_LAT_ENC
    , ENTRY_GPS_LON_ENC
    , ENTRY_DISTANCE_M
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (

      CONCAT('A', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL('__GLOBAL__', 'TBM_ATTENDANCE_CD'))
    , #{cmpnyCd}
    , #{sessionCd}
    , #{userTypeCd}
    , #{userCd}
    , #{entryTypeCd}
    , NOW()
    , #{latEnc}
    , #{lonEnc}
    , #{distanceM}
    , 'N'
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.update:
/* AppTbm01Mapper.restoreAttendance */
UPDATE TB_TBM_ATTENDANCE
SET
      DEL_YN                    = 'N'
    , ENTRY_TYPE_CD              = #{entryTypeCd}
    , ENTRY_BY_MANAGER_USER_CD   = NULL
    , ENTRY_AT                   = NOW()
    , ENTRY_GPS_LAT              = NULL
    , ENTRY_GPS_LON              = NULL
    , ENTRY_GPS_LAT_ENC          = #{latEnc}
    , ENTRY_GPS_LON_ENC          = #{lonEnc}
    , ENTRY_DISTANCE_M           = #{distanceM}
    , APP_FOREGROUND_SEC         = NULL
    , EXIT_TYPE_CD               = NULL
    , EXIT_BY_MANAGER_USER_CD    = NULL
    , EXIT_AT                    = NULL
    , EXIT_SIGN_FILE_MGMT_CD     = NULL
    , EXIT_FORCED_REASON         = NULL
    , COMPLETION_STATUS_CD       = NULL
    , NOT_COMPLETED_REASON       = NULL
    , STATUS_UPDATED_BY          = NULL
    , STATUS_UPDATED_AT          = NULL
    , UPDATE_NO                  = #{insertNo}
    , UPDATE_DATE                = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'Y'

/* AppTbm01Mapper.updateExit */
UPDATE TB_TBM_ATTENDANCE
SET
      EXIT_TYPE_CD           = #{exitTypeCd}
    , EXIT_AT                = NOW()
    , EXIT_SIGN_FILE_MGMT_CD = #{exitSignFileMgmtCd}
    , COMPLETION_STATUS_CD   = #{completionStatusCd}
    /* prafta-051-08: 앱 포그라운드 누적초(nullable). null 이면 그대로 NULL 저장. */
    , APP_FOREGROUND_SEC     = #{appForegroundSec}
    , STATUS_UPDATED_BY      = #{updateNo}
    , STATUS_UPDATED_AT      = NOW()
    , UPDATE_NO              = #{updateNo}
    , UPDATE_DATE            = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'
  AND EXIT_AT IS NULL

mapper.select:
/* AppTbm01Mapper.selectInProgressSessions */

SELECT
      S.SESSION_CD                                                       AS sessionCd
    , S.TITLE                                                            AS title
    , FNC_CMM_INFO_SRCH(S.CMPNY_CD, 'USER_NM', S.MANAGER_USER_CD, NULL)  AS managerUserNm
    , DATE_FORMAT(S.OPENED_AT, '%Y-%m-%d %H:%i')                         AS openedAt
    , DATE_FORMAT(S.STARTED_AT, '%Y-%m-%d %H:%i')                        AS startedAt
    , NULL                                                               AS endedAt
    , NULL                                                               AS completionStatusCd
    ,                                  AS hostCmpnyNm
FROM TB_TBM_SESSION S
WHERE S.STATUS_CD = 'IN_PROGRESS'
  AND S.DEL_YN = 'N'
  AND (
        (S.CMPNY_CD = #{cmpnyCd} AND S.SITE_CD = #{siteCd})
     OR (
          S.CMPNY_CD <> #{cmpnyCd}
      AND (
            EXISTS (SELECT 1 FROM REACH R WHERE R.SESSION_CD = S.SESSION_CD)

         OR EXISTS (
                SELECT 1
                FROM TB_TBM_ATTENDANCE GA
                WHERE GA.CMPNY_CD = #{cmpnyCd}
                  AND GA.SESSION_CD = S.SESSION_CD
                  AND GA.USER_TYPE_CD = #{userTypeCd}
                  AND GA.USER_CD = #{userCd}
                  AND GA.DEL_YN = 'N'
            )
          )
        )
  )

  AND EXISTS (
        SELECT 1
        FROM TB_TBM_ATTENDANCE AT
        WHERE AT.CMPNY_CD = #{cmpnyCd}
          AND AT.SESSION_CD = S.SESSION_CD
          AND AT.USER_TYPE_CD = #{userTypeCd}
          AND AT.USER_CD = #{userCd}
          AND AT.DEL_YN = 'N'
      )
ORDER BY S.STARTED_AT DESC, S.SESSION_CD DESC

/* AppTbm01Mapper.selectSessionContentBody */
SELECT
    S.CONTENT_BODY
FROM TB_TBM_SESSION S

WHERE S.CMPNY_CD = #{sessionCmpnyCd}
  AND S.SESSION_CD = #{sessionCd}
  AND S.DEL_YN = 'N'

/* AppTbm01Mapper.selectSessionContentItems */ SELECT I.MTRL_CD AS mtrlCd , I.MTRL_ITEM_CD AS mtrlItemCd , I.MTRL_ITEM_TYPE AS itemType , I.FILE_MGMT_CD AS fileMgmtCd , I.URL AS url , I.MTRL_DESC AS itemDesc , I.SORT_IDX AS sortIdx
, F.FILE_PATH AS filePath , F.FILE_EXT AS fileExt FROM TB_TBM_EDU_MTRL_ITEM I
INNER JOIN TB_TBM_SESSION_CONTENT SC ON ( I.CMPNY_CD = SC.CMPNY_CD AND I.MTRL_CD = SC.MTRL_CD ) LEFT OUTER JOIN TB_FILE_INFO F ON ( F.CMPNY_CD = SC.CMPNY_CD AND F.FILE_MGMT_CD = I.FILE_MGMT_CD )
WHERE SC.CMPNY_CD = #{sessionCmpnyCd}
AND I.CMPNY_CD = #{sessionCmpnyCd} AND SC.SESSION_CD = #{sessionCd} AND I.USE_YN = 'Y'
AND EXISTS ( SELECT 1 FROM TB_TBM_EDU_MTRL M WHERE M.MTRL_CD = I.MTRL_CD AND M.CMPNY_CD = I.CMPNY_CD ) AND EXISTS ( SELECT 1 FROM TB_TBM_SESSION S WHERE S.CMPNY_CD = SC.CMPNY_CD AND S.SESSION_CD = SC.SESSION_CD AND S.DEL_YN = 'N' ) ORDER BY SC.DISPLAY_ORDER, I.SORT_IDX

/* AppTbm01Mapper.selectMyCompletion */
SELECT
      S.TITLE                                                         AS title
    , S.CONTENT_BODY                                                  AS contentBody
    , AT.EXIT_SIGN_FILE_MGMT_CD                                       AS mySignFileMgmtCd
    , AT.COMPLETION_STATUS_CD                                         AS completionStatusCd
    , DATE_FORMAT(IFNULL(S.ENDED_AT, AT.EXIT_AT), '%Y-%m-%d %H:%i')   AS endedAt

    , F.FILE_PATH                                                     AS signFilePath
    , F.FILE_EXT                                                      AS signFileExt
FROM TB_TBM_ATTENDANCE AT

     INNER JOIN TB_TBM_SESSION S
        ON (
            S.CMPNY_CD = #{sessionCmpnyCd}
        AND AT.SESSION_CD = S.SESSION_CD
        )
     LEFT OUTER JOIN TB_FILE_INFO F
        ON (
            F.CMPNY_CD = AT.CMPNY_CD
        AND F.FILE_MGMT_CD = AT.EXIT_SIGN_FILE_MGMT_CD
        )
WHERE AT.CMPNY_CD = #{cmpnyCd}
  AND AT.SESSION_CD = #{sessionCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'
  AND S.DEL_YN = 'N'

