/* AppTbm01Mapper.deleteAttendance */
DELETE FROM TB_TBM_ATTENDANCE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'
  AND EXIT_AT IS NULL

